void drawCalendar(const Calendar& calendar1, const Calendar& calendar2)
{
    epaper.fillScreen(TFT_WHITE);

    time_t now = time(nullptr);

    struct tm nowTm;
    localtime_r(&now, &nowTm);

    drawCalendarGrid(nowTm);
    drawCalendarEvents(calendar1, now);
    drawCalendarEvents(calendar2, now);

    epaper.update();
}

void drawCalendarGrid(struct tm nowTm)
{
    const char* days[] =
    {
        "Mon",
        "Tue",
        "Wed",
        "Thu",
        "Fri",
        "Sat",
        "Sun"
    };

    for(int i = 0; i < 7; i++)
    {
        epaper.drawLine(COLUMN_X[i], -1, COLUMN_X[i], 479, TFT_BLACK);
    }

    epaper.drawLine(800, -1, 800, 479, TFT_BLACK);

    for(int h = 6; h <= 22; h++)
    {
        int y = GRID_TOP_Y + (h - 6) * HOUR_HEIGHT;

        epaper.drawLine(30, y, 830, y, TFT_BLACK);

        epaper.setTextColor(TFT_BLACK);
        epaper.setTextSize(1);

        if(h < 10)
            epaper.setCursor(4, y - 4);
        else
            epaper.setCursor(0, y - 4);

        epaper.print(h);
        epaper.print(":00");
    }

    struct tm monday = nowTm;

    int offset = (nowTm.tm_wday + 6) % 7;

    monday.tm_mday -= offset;
    mktime(&monday);

    epaper.setTextSize(2);

    for(int i = 0; i < 7; i++)
    {
        struct tm day = monday;
        day.tm_mday += i;
        mktime(&day);

        int x = COLUMN_X[i];

        epaper.setCursor(x + 34, 8);
        epaper.print(days[i]);

        epaper.setTextSize(2);

        char buffer[3];
        sprintf(buffer, "%d", day.tm_mday);

        int centerX = x + DAY_WIDTH / 2;
        int textWidth = strlen(buffer) * 12;
        int textX = centerX - textWidth / 2;

        if(day.tm_mday == nowTm.tm_mday &&
           day.tm_mon == nowTm.tm_mon &&
           day.tm_year == nowTm.tm_year)
        {
            epaper.drawRect(
                centerX - 11,
                23,
                22,
                22,
                TFT_BLACK
            );
        }

        epaper.setCursor(textX, 27);
        epaper.print(buffer);

        epaper.setTextSize(2);
    }

    int currentDay = (nowTm.tm_wday + 6) % 7;

    int minutesSince6 =
        nowTm.tm_hour * 60 +
        nowTm.tm_min -
        360;

    minutesSince6 = constrain(minutesSince6, 0, 16 * 60);

    int bitmapY =
        GRID_TOP_Y +
        (minutesSince6 * HOUR_HEIGHT) / 60 -
        5;

    int bitmapX =
        COLUMN_X[currentDay] - 3;

    epaper.drawBitmap(
        bitmapX,
        bitmapY,
        image_paint_64_bits,
        115,
        10,
        TFT_BLACK
    );
}

void drawCalendarEvents(
    const Calendar& calendar,
    time_t now)
{
    epaper.setTextSize(1);

    for(uint8_t i = 0; i < calendar.eventCount(); i++)
    {
        const Calendar::Event& e = calendar.event(i);

        struct tm startTm;
        struct tm endTm;

        localtime_r(&e.start, &startTm);
        localtime_r(&e.end, &endTm);

        int day = (startTm.tm_wday + 6) % 7;

        if(day < 0 || day > 6)
            continue;

        int startMinutes =
            startTm.tm_hour * 60 +
            startTm.tm_min;

        int endMinutes =
            endTm.tm_hour * 60 +
            endTm.tm_min;

        int y =
            GRID_TOP_Y +
            ((startMinutes - 360) * HOUR_HEIGHT) / 60;

        int h =
            ((endMinutes - startMinutes) * HOUR_HEIGHT) / 60;

        if(h < 12)
            h = 12;

        int x = COLUMN_X[day] + 3;

        bool finished = e.end < now;

        if(finished)
        {
            epaper.drawRect(
                x,
                y,
                102,
                h,
                TFT_BLACK);

            epaper.setTextColor(TFT_BLACK);
        }
        else
        {
            epaper.fillRect(
                x,
                y,
                102,
                h,
                TFT_BLACK);

            epaper.setTextColor(TFT_WHITE);
        }

        epaper.setCursor(
            x + 3,
            y + 3);

        epaper.print(e.title);

        epaper.setTextColor(TFT_BLACK);
    }
}

void drawClockFace(int16_t cx, int16_t cy, int16_t radius)
{
    epaper.fillScreen(TFT_WHITE);

    epaper.fillCircle(
      cx,
      cy,
      radius,
      TFT_BLACK
    );

    epaper.fillCircle(
      cx,
      cy,
      radius - 12,
      TFT_WHITE
    );


    // Hour marks
    for (int i = 0; i < 360; i += 30)
    {
      float sx = cos((i - 90) * 0.0174532925);
      float sy = sin((i - 90) * 0.0174532925);

      epaper.drawLine(
        sx * (radius - 10) + cx,
        sy * (radius - 10) + cy,
        sx * (radius - 45) + cx,
        sy * (radius - 45) + cy,
        TFT_BLACK
      );
    }


    // Minute marks
    for (int i = 0; i < 360; i += 6)
    {
      float sx = cos((i - 90) * 0.0174532925);
      float sy = sin((i - 90) * 0.0174532925);

      int16_t x = sx * (radius - 38) + cx;
      int16_t y = sy * (radius - 38) + cy;

      epaper.drawPixel(
        x,
        y,
        TFT_BLACK
      );

      if (i % 90 == 0)
      {
        epaper.fillCircle(
          x,
          y,
          3,
          TFT_BLACK
        );
      }
    }


    epaper.fillCircle(
      cx,
      cy,
      5,
      TFT_BLACK
    );
}

void drawAccurateClock()
{
    const int16_t cx = 400;
    const int16_t cy = 240;
    const int16_t radius = 195; //195

    const int16_t updateX = cx - radius - 15;
    const int16_t updateY = cy - radius - 15;
    const int16_t updateSize = radius * 2 + 30;

    int16_t oldHx = cx;
    int16_t oldHy = cy;
    int16_t oldMx = cx;
    int16_t oldMy = cy;

    bool firstDraw = true;

    int lastMinute = -1;
    int partialCount = 0;

    // Draw static background once
    drawClockFace(cx, cy, radius);

    //epaper.fillScreen(TFT_WHITE);
    epaper.update();

    while (true)
    {
        //epaper.fillScreen(TFT_WHITE);
        struct tm timeinfo;

        if (getLocalTime(&timeinfo))
        {
            int hh = timeinfo.tm_hour;
            int mm = timeinfo.tm_min;

            if (mm != lastMinute)
            {
                lastMinute = mm;

                float mdeg = mm * 6.0f;
                float hdeg = (hh % 12) * 30.0f + mdeg / 12.0f;

                float mx = cos((mdeg - 90) * 0.0174532925f);
                float my = sin((mdeg - 90) * 0.0174532925f);

                float hx = cos((hdeg - 90) * 0.0174532925f);
                float hy = sin((hdeg - 90) * 0.0174532925f);

                int16_t newMx = mx * 154 + cx;
                int16_t newMy = my * 154 + cy;

                int16_t newHx = hx * 114 + cx;
                int16_t newHy = hy * 114 + cy;

                // Erase previous hands (skip first time)
                if (!firstDraw)
                {
                    epaper.drawLine(oldMx, oldMy, cx, cy, TFT_WHITE);
                    epaper.drawLine(oldHx, oldHy, cx, cy, TFT_WHITE);
                    epaper.drawLine(oldMx, oldMy, cx, cy, TFT_WHITE);
                    epaper.drawLine(oldHx, oldHy, cx, cy, TFT_WHITE);
                }

                // Draw new hands
                epaper.drawLine(newMx, newMy, cx, cy, TFT_BLACK);
                epaper.drawLine(newHx, newHy, cx, cy, TFT_BLACK);
                epaper.drawLine(newMx, newMy, cx, cy, TFT_BLACK);
                epaper.drawLine(newHx, newHy, cx, cy, TFT_BLACK);

                // Restore centre cap
                epaper.fillCircle(cx, cy, 5, TFT_BLACK);

                oldMx = newMx;
                oldMy = newMy;
                oldHx = newHx;
                oldHy = newHy;

                firstDraw = false;

                // epaper.updataPartial(
                //     updateX,
                //     updateY,
                //     updateSize,
                //     updateSize
                // );

                // epaper.updataPartial(
                //     300,
                //     140,
                //     200,
                //     200
                // );
                epaper.update();

                partialCount++;

                if (partialCount >= 30)
                {
                    // Rebuild framebuffer completely
                    drawClockFace(cx, cy, radius);

                    epaper.drawLine(oldMx, oldMy, cx, cy, TFT_BLACK);
                    epaper.drawLine(oldHx, oldHy, cx, cy, TFT_BLACK);
                    epaper.drawLine(oldMx, oldMy, cx, cy, TFT_BLACK);
                    epaper.drawLine(oldHx, oldHy, cx, cy, TFT_BLACK);

                    epaper.fillCircle(cx, cy, 5, TFT_BLACK);

                    epaper.update();

                    partialCount = 0;
                }
            }
        }

        delay(1000);
    }
}

