enum WindDirection { NORTH, EAST, SOUTH, WEST };

WindDirection degreesToDirection(int degrees)
{
  degrees = degrees % 360;
  if (degrees < 0) degrees += 360;
  if (degrees >= 315 || degrees < 45) return NORTH;
  if (degrees >= 45 && degrees < 135) return EAST;
  if (degrees >= 135 && degrees < 225) return SOUTH;
  return WEST;
}


const unsigned char* getWeatherIcon(Weather::WeatherCondition cond, uint16_t* w, uint16_t* h)
{
  switch (cond)
  {
    case Weather::WeatherCondition::ClearSky:
    case Weather::WeatherCondition::MainlyClear:
        *w = 51; *h = 48; return image_weather_cloud_sunny_bits;
    case Weather::WeatherCondition::PartlyCloudy:
    case Weather::WeatherCondition::Overcast:
        *w = 68; *h = 64; return image_weather_cloud_rain_1_bits;
    case Weather::WeatherCondition::LightDrizzle:
    case Weather::WeatherCondition::ModerateDrizzle:
    case Weather::WeatherCondition::DenseDrizzle:
    case Weather::WeatherCondition::LightFreezingDrizzle:
    case Weather::WeatherCondition::DenseFreezingDrizzle:
    case Weather::WeatherCondition::SlightRain:
    case Weather::WeatherCondition::ModerateRain:
    case Weather::WeatherCondition::HeavyRain:
    case Weather::WeatherCondition::LightFreezingRain:
    case Weather::WeatherCondition::HeavyFreezingRain:
    case Weather::WeatherCondition::SlightRainShowers:
    case Weather::WeatherCondition::ModerateRainShowers:
    case Weather::WeatherCondition::ViolentRainShowers:
        *w = 68; *h = 64; return image_weather_cloud_rain_1_bits;
    case Weather::WeatherCondition::Thunderstorm:
    case Weather::WeatherCondition::ThunderstormWithSlightHail:
    case Weather::WeatherCondition::ThunderstormWithHeavyHail:
        *w = 68; *h = 56; return image_weather_cloud_lightning_bolt_bits;
    case Weather::WeatherCondition::SlightSnowfall:
    case Weather::WeatherCondition::ModerateSnowfall:
    case Weather::WeatherCondition::HeavySnowfall:
    case Weather::WeatherCondition::SnowGrains:
    case Weather::WeatherCondition::SlightSnowShowers:
        *w = 68; *h = 56; return image_weather_cloud_snow_bits;
    default:
        *w = 51; *h = 48; return image_weather_cloud_sunny_bits;
  }
}


const unsigned char* getWindArrow(WindDirection dir, uint16_t* w, uint16_t* h)
{
    *w = 15; *h = 15;
    switch (dir)
    {
        case NORTH: return image_music_play_copy_1_bits;
        case EAST: return image_music_play_bits;
        case SOUTH: return image_music_play_copy_2_bits;
        case WEST: return image_music_play_copy_3_bits;
        default: return nullptr;
    }
}

